export function AuthForm({ register = false }: { register?: boolean }) {
  const { update } = useAuth();
  const navigate = useNavigate();
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");
    setBusy(true);
    const form = new FormData(event.currentTarget);
    const data: Record<string, string> = {
      email: String(form.get("email")),
      password: String(form.get("password")),
    };
    if (register)
      data.username = String(form.get("username")).trim().toLowerCase();
    try {
      update(
        await request(register ? "register" : "login", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(data),
        }),
      );
      navigate("/");
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(false);
    }
  }
  return (
    <section className="auth-form">
      <h1>{register ? "Регистрация" : "Вход"}</h1>
      <form onSubmit={submit}>
        <label>
          Email
          <input
            name="email"
            type="email"
            autoComplete="email"
            required
            maxLength={320}
          />
        </label>
        {register && (
          <label>
            Имя пользователя
            <input
              name="username"
              autoComplete="username"
              required
              minLength={3}
              maxLength={32}
              pattern="[A-Za-z0-9_]+"
              title="3–32 латинских буквы, цифры или подчёркивание"
            />
          </label>
        )}
        <label>
          Пароль
          <input
            name="password"
            type="password"
            autoComplete={register ? "new-password" : "current-password"}
            required
            minLength={12}
            maxLength={128}
          />
        </label>
        {error && <p role="alert">{error}</p>}
        <button disabled={busy}>
          {busy ? "Подождите…" : register ? "Зарегистрироваться" : "Войти"}
        </button>
      </form>
      <Link to={register ? "/login" : "/register"}>
        {register ? "Уже есть аккаунт? Войти" : "Создать аккаунт"}
      </Link>
    </section>
  );
}
